int main(int argc,char **argv)
{
    assert(argc==2);
    if (strcmp(argv[1],"div1")==0) { pclk=16000000U;divider=RCC_HCLK_DIV1; }
    if (strcmp(argv[1],"bad-divider")==0) { divider=8U; }
