    for label in ('original','fixed'):
        functions=[]
        for path,name in zip(paths,('HAL_Init','HAL_RCC_ClockConfig')):
            data=files[path] if label=='original' else rendered[replacements['HardwareGenerated/NativeClassicCdc/'+path]]
